var DECKS={"m-f": "Funções orgânicas", "m-o": "Orgânica: reações e isomeria", "m-i": "Inorgânica", "m-p": "Físico-química", "m-g": "Geral e átomo", "m-b": "Polímeros e bioquímica", "a-frente-1": "Frente 1: tabelas e conceitos", "a-frente-2": "Frente 2: tabelas e conceitos", "a-frente-3": "Frente 3: tabelas e conceitos", "a-frente-4": "Frente 4: tabelas e conceitos", "a-organica": "Orgânica: tabelas e conceitos"};var CARDS=[["m-f", "Qual função tem o grupo –OH em carbono saturado?", "Álcool · sufixo -ol · ex.: etanol", "organica/funcoes-hidrocarbonetos"], ["m-f", "Grupo e sufixo da função Álcool", "–OH em carbono saturado · -ol", "organica/funcoes-hidrocarbonetos"], ["m-f", "Qual função tem o grupo –OH em carbono do anel aromático?", "Fenol · sufixo hidróxi-benzeno · ex.: fenol (antisséptico)", "organica/funcoes-hidrocarbonetos"], ["m-f", "Grupo e sufixo da função Fenol", "–OH em carbono do anel aromático · hidróxi-benzeno", "organica/funcoes-hidrocarbonetos"], ["m-f", "Qual função tem o grupo R–O–R′ (O entre carbonos)?", "Éter · sufixo -oxi- (prefixo) · ex.: etoxietano", "organica/funcoes-hidrocarbonetos"], ["m-f", "Grupo e sufixo da função Éter", "R–O–R′ (O entre carbonos) · -oxi- (prefixo)", "organica/funcoes-hidrocarbonetos"], ["m-f", "Qual função tem o grupo –CHO (carbonila na ponta da cadeia)?", "Aldeído · sufixo -al · ex.: metanal (formol)", "organica/funcoes-hidrocarbonetos"], ["m-f", "Grupo e sufixo da função Aldeído", "–CHO (carbonila na ponta da cadeia) · -al", "organica/funcoes-hidrocarbonetos"], ["m-f", "Qual função tem o grupo C=O entre dois carbonos?", "Cetona · sufixo -ona · ex.: propanona (acetona)", "organica/funcoes-hidrocarbonetos"], ["m-f", "Grupo e sufixo da função Cetona", "C=O entre dois carbonos · -ona", "organica/funcoes-hidrocarbonetos"], ["m-f", "Qual função tem o grupo –COOH?", "Ácido carboxílico · sufixo ácido …-óico · ex.: ácido etanoico (vinagre)", "organica/funcoes-hidrocarbonetos"], ["m-f", "Grupo e sufixo da função Ácido carboxílico", "–COOH · ácido …-óico", "organica/funcoes-hidrocarbonetos"], ["m-f", "Qual função tem o grupo R–COO–R′?", "Éster · sufixo -oato de …-ila · ex.: etanoato de etila (aromas)", "organica/funcoes-hidrocarbonetos"], ["m-f", "Grupo e sufixo da função Éster", "R–COO–R′ · -oato de …-ila", "organica/funcoes-hidrocarbonetos"], ["m-f", "Qual função tem o grupo R–COO⁻ M⁺?", "Sal orgânico · sufixo -oato de … · ex.: sabão", "organica/funcoes-hidrocarbonetos"], ["m-f", "Grupo e sufixo da função Sal orgânico", "R–COO⁻ M⁺ · -oato de …", "organica/funcoes-hidrocarbonetos"], ["m-f", "Qual função tem o grupo –NH₂ (derivada da amônia)?", "Amina · sufixo -amina · ex.: etilamina", "organica/funcoes-hidrocarbonetos"], ["m-f", "Grupo e sufixo da função Amina", "–NH₂ (derivada da amônia) · -amina", "organica/funcoes-hidrocarbonetos"], ["m-f", "Qual função tem o grupo –CONH₂?", "Amida · sufixo -amida · ex.: ureia", "organica/funcoes-hidrocarbonetos"], ["m-f", "Grupo e sufixo da função Amida", "–CONH₂ · -amida", "organica/funcoes-hidrocarbonetos"], ["m-f", "Qual função tem o grupo –C≡N?", "Nitrila · sufixo -nitrila · ex.: acetonitrila", "organica/funcoes-hidrocarbonetos"], ["m-f", "Grupo e sufixo da função Nitrila", "–C≡N · -nitrila", "organica/funcoes-hidrocarbonetos"], ["m-f", "Qual função tem o grupo R–X (F, Cl, Br, I)?", "Haleto orgânico · sufixo fluoro-, cloro-, bromo-, iodo- · ex.: cloroetano", "organica/funcoes-hidrocarbonetos"], ["m-f", "Grupo e sufixo da função Haleto orgânico", "R–X (F, Cl, Br, I) · fluoro-, cloro-, bromo-, iodo-", "organica/funcoes-hidrocarbonetos"], ["m-f", "Qual função tem o grupo –NO₂?", "Nitrocomposto · sufixo nitro- · ex.: TNT", "organica/funcoes-hidrocarbonetos"], ["m-f", "Grupo e sufixo da função Nitrocomposto", "–NO₂ · nitro-", "organica/funcoes-hidrocarbonetos"], ["m-f", "Qual função tem o grupo –SH?", "Tiol · sufixo -tiol · ex.: etanotiol (cheiro do gás de cozinha)", "organica/funcoes-hidrocarbonetos"], ["m-f", "Grupo e sufixo da função Tiol", "–SH · -tiol", "organica/funcoes-hidrocarbonetos"], ["m-o", "Quando existe isomeria geométrica (cis-trans)?", "Dupla (ou anel) e dois ligantes diferentes em cada carbono da dupla.", ""], ["m-o", "Quando existe isomeria óptica? Quantos isômeros?", "Carbono quiral (4 ligantes diferentes). Com n quirais diferentes: 2ⁿ ativos e 2ⁿ⁻¹ misturas racêmicas.", ""], ["m-o", "Regra de Markovnikov", "Na adição de HX a alceno, o H vai para o carbono da dupla mais hidrogenado.", ""], ["m-o", "Oxidação de álcoois", "Primário → aldeído → ácido; secundário → cetona; terciário não oxida.", ""], ["m-o", "Ordem de ponto de ebulição (massas parecidas)", "Ácido carboxílico > álcool > aldeído/cetona > éter > hidrocarboneto. Ramificado ferve menos que o normal.", ""], ["m-o", "Ordem de acidez orgânica", "Ácido carboxílico > fenol > água > álcool.", ""], ["m-o", "Etanol + H₂SO₄ conc. a 170 °C e a 140 °C", "170 °C: eteno (intramolecular). 140 °C: éter dietílico (intermolecular).", ""], ["m-o", "Hibridização, geometria e ângulo: sp³, sp², sp", "sp³: tetraédrica, 109°28′. sp²: trigonal plana, 120°. sp: linear, 180°.", ""], ["m-o", "Benzeno: tipo de reação preferida", "Substituição (ressonância). Orto-para dirigentes: –OH, –NH₂, –CH₃, halogênios. Meta: –NO₂, –COOH, –CHO.", ""], ["m-i", "Força de oxiácido", "nº de O − nº de H ionizáveis: 0 fraco, 1 moderado, ≥ 2 forte (H₂CO₃ é exceção: fraco).", ""], ["m-i", "Sufixos: ácido → sal", "-ídrico → -eto; -ico → -ato; -oso → -ito.", ""], ["m-i", "Quando a dupla troca ocorre?", "Se formar precipitado, gás ou eletrólito mais fraco (incluindo água).", ""], ["m-i", "Sais sempre solúveis", "1A, NH₄⁺, nitratos e acetatos. Sulfatos solúveis, exceto Ca²⁺, Sr²⁺, Ba²⁺, Pb²⁺.", ""], ["m-i", "Óxidos anfóteros e neutros", "Anfóteros: ZnO, Al₂O₃. Neutros: CO, NO, N₂O.", ""], ["m-i", "Brønsted-Lowry × Lewis", "BL: ácido doa H⁺, base recebe H⁺. Lewis: ácido recebe par de elétrons, base doa (BF₃ é ácido de Lewis).", ""], ["m-i", "Simples troca: quando ocorre?", "Só se o elemento livre for mais reativo (metais: K > Na > Ca > Mg > Al > Zn > Fe > H > Cu > Ag > Au).", ""], ["m-p", "ΔG e espontaneidade", "ΔG = ΔH − T·ΔS. ΔG < 0: espontâneo.", ""], ["m-p", "Le Chatelier", "↑T desloca para o endotérmico; ↑P para o lado com menos mols gasosos; catalisador não desloca. Só T muda o K.", ""], ["m-p", "Kc", "[produtos]/[reagentes] com expoentes = coeficientes. Sólidos e líquidos puros não entram.", ""], ["m-p", "Catalisador", "Menor Ea; não altera ΔH, rendimento nem K.", ""], ["m-p", "Hidrólise salina", "O íon do eletrólito fraco reage com a água. Ác. fraco + base forte: pH > 7. Ác. forte + base fraca: pH < 7.", ""], ["m-p", "Pilha: ânodo, cátodo e ΔE°", "Ânodo: oxidação, polo −. Cátodo: redução, polo +. ΔE° = E°red(cátodo) − E°red(ânodo) > 0.", ""], ["m-p", "Eletrólise aquosa: facilidade de descarga", "Cátions: metais comuns > H⁺ > 1A, 2A, Al³⁺. Ânions: não oxigenados > OH⁻ > oxigenados e F⁻.", ""], ["m-p", "Faraday", "Q = i·t; 1 mol de e⁻ = 96 500 C.", ""], ["m-p", "Propriedades coligativas", "Dependem só do nº de partículas. Compare por i: glicose 1, NaCl 2, CaCl₂ 3.", ""], ["m-g", "Raio, EI e eletronegatividade na tabela", "Raio cresce ↓ e ←. EI, EN e afinidade crescem ↑ e →. Isoeletrônicos: maior Z, menor raio.", ""], ["m-g", "Pauli e Hund", "Pauli: no mesmo orbital, spins opostos. Hund: um elétron em cada orbital de mesma energia antes de emparelhar.", ""], ["m-g", "Geometria e ângulo: CO₂, BF₃, H₂O, NH₃, CH₄", "CO₂ linear 180°; BF₃ plana 120°; H₂O angular 104,5°; NH₃ piramidal 107°; CH₄ tetraédrica 109,5°.", ""], ["m-g", "Forças intermoleculares", "Dipolo induzido < dipolo permanente < ligação de hidrogênio (H com F, O ou N).", ""], ["m-g", "Radiações α, β, γ", "α: Z−2, A−4. β⁻: Z+1, A igual. γ: não muda Z nem A.", ""], ["m-g", "Meia-vida", "m = m₀/2ˣ, com x = t/P.", ""], ["m-g", "Reagente limitante", "Divida o n de cada reagente pelo seu coeficiente: o menor valor é o limitante.", ""], ["m-g", "Mol e volume molar", "6,02·10²³ entidades; 22,4 L nas CNTP; n = m/M.", ""], ["m-b", "Adição × condensação", "Adição: abre a dupla C=C, nada é liberado (PE, PVC). Condensação: libera H₂O (náilon, PET).", ""], ["m-b", "Ligação peptídica", "Amida (–CO–NH–). n aminoácidos formam n − 1 ligações.", ""], ["m-b", "Saponificação", "Triglicerídeo + 3 NaOH → 3 sabão + glicerol.", ""], ["m-b", "Dissacarídeos", "Sacarose = glicose + frutose; lactose = glicose + galactose; maltose = glicose + glicose.", ""], ["m-b", "DNA × RNA", "DNA: desoxirribose, T, dupla hélice. RNA: ribose, U, fita simples. A–T (2 ligações), C–G (3).", ""], ["m-b", "Estruturas das proteínas", "1ª: sequência. 2ª: α-hélice/folha β (ligações de H). 3ª: dobramento 3D. 4ª: várias cadeias.", ""], ["a-frente-1", "Evolução dos modelos atômicos\nDalton (1803)\n(Evidência, Ideia, Limitação)", "Evidência: Leis ponderais (Lavoisier, Proust) · Ideia: Esfera maciça, indivisível e indestrutível. Átomos de um elemento são iguais; compostos são combinações de átomos. · Limitação: Não explica eletricidade nem a divisibilidade do átomo.", "frente-1/atomo"], ["a-frente-1", "Evolução dos modelos atômicos\nThomson (1897)\n(Evidência, Ideia, Limitação)", "Evidência: Tubo de raios catódicos: partículas negativas · Ideia: Esfera positiva neutralizada por elétrons incrustados (\"pudim de passas\"). Descobre o elétron . · Limitação: Não prevê o núcleo.", "frente-1/atomo"], ["a-frente-1", "Evolução dos modelos atômicos\nRutherford (1911)\n(Evidência, Ideia, Limitação)", "Evidência: Folha de ouro bombardeada com α: a maioria passa; poucas desviam; pouquíssimas voltam · Ideia: Núcleo pequeno, denso e positivo; eletrosfera enorme e quase vazia, com elétrons girando (modelo planetário). · Limitação: Pela física clássica o elétron em órbita perderia energia e cairia no núcleo.", "frente-1/atomo"], ["a-frente-1", "Evolução dos modelos atômicos\nBohr (1913)\n(Evidência, Ideia, Limitação)", "Evidência: Espectros de linhas do hidrogênio · Ideia: Elétrons em órbitas estacionárias (níveis quantizados). Saltar para nível mais externo absorve energia; voltar emite luz (fóton) de energia exata E = h·ν. · Limitação: Só funciona bem para o hidrogênio.", "frente-1/atomo"], ["a-frente-1", "Evolução dos modelos atômicos\nSommerfeld\n(Evidência, Ideia, Limitação)", "Evidência: Estrutura fina dos espectros · Ideia: Órbitas elípticas e subníveis dentro dos níveis. · Limitação: Ainda tratava o elétron como partícula.", "frente-1/atomo"], ["a-frente-1", "Evolução dos modelos atômicos\nOrbital (Schrödinger)\n(Evidência, Ideia, Limitação)", "Evidência: De Broglie (dualidade onda-partícula), Heisenberg (incerteza) · Ideia: Não se determina posição e velocidade ao mesmo tempo. Orbital : região de maior probabilidade de encontrar o elétron. · Limitação: Modelo atual.", "frente-1/atomo"], ["a-frente-1", "Átomo, íons e isótopos\nPróton (p)\n(Carga relativa, Massa relativa, Local)", "Carga relativa: +1 · Massa relativa: 1 · Local: núcleo", "frente-1/atomo"], ["a-frente-1", "Átomo, íons e isótopos\nNêutron (n)\n(Carga relativa, Massa relativa, Local)", "Carga relativa: 0 · Massa relativa: 1 · Local: núcleo", "frente-1/atomo"], ["a-frente-1", "Átomo, íons e isótopos\nElétron (e⁻)\n(Carga relativa, Massa relativa, Local)", "Carga relativa: −1 · Massa relativa: ≈ 1/1836 · Local: eletrosfera", "frente-1/atomo"], ["a-frente-1", "Átomo, íons e isótopos\nIsótopos\n(Mesmo, Exemplo)", "Mesmo: Z · Exemplo: ¹H, ²H (deutério), ³H (trítio); ¹²C, ¹⁴C", "frente-1/atomo"], ["a-frente-1", "Átomo, íons e isótopos\nIsóbaros\n(Mesmo, Exemplo)", "Mesmo: A · Exemplo: ⁴⁰K e ⁴⁰Ca", "frente-1/atomo"], ["a-frente-1", "Átomo, íons e isótopos\nIsótonos\n(Mesmo, Exemplo)", "Mesmo: nº de nêutrons · Exemplo: ¹¹B (N = 6) e ¹²C (N = 6)", "frente-1/atomo"], ["a-frente-1", "Átomo, íons e isótopos\nIsoeletrônicos\n(Mesmo, Exemplo)", "Mesmo: nº de elétrons · Exemplo: O²⁻, F⁻, Ne, Na⁺, Mg²⁺ (10 e⁻)", "frente-1/atomo"], ["a-frente-1", "Eletrosfera e distribuição eletrônica\nn (principal)\n(Indica, Valores)", "Indica: nível · Valores: 1, 2, 3...", "frente-1/atomo"], ["a-frente-1", "Eletrosfera e distribuição eletrônica\nℓ (secundário)\n(Indica, Valores)", "Indica: subnível · Valores: 0 (s), 1 (p), 2 (d), 3 (f); vai de 0 a n−1", "frente-1/atomo"], ["a-frente-1", "Eletrosfera e distribuição eletrônica\nmℓ (magnético)\n(Indica, Valores)", "Indica: orbital · Valores: de −ℓ a +ℓ", "frente-1/atomo"], ["a-frente-1", "Eletrosfera e distribuição eletrônica\nmₛ (spin)\n(Indica, Valores)", "Indica: sentido de rotação · Valores: +½ ou −½", "frente-1/atomo"], ["a-frente-1", "Eletrosfera e distribuição eletrônica\nCamada de valência?", "a mais externa (maior n). Subnível mais energético: o último na ordem de Pauling.", "frente-1/atomo"], ["a-frente-1", "Eletrosfera e distribuição eletrônica\nCátions?", "retire elétrons da camada de valência (maior n), não do subnível mais energético. Ânions: acrescente elétrons ao subnível incompleto.", "frente-1/atomo"], ["a-frente-1", "Eletrosfera e distribuição eletrônica\nPauli?", "não existem dois elétrons com os 4 números quânticos iguais (num orbital, spins opostos).", "frente-1/atomo"], ["a-frente-1", "Eletrosfera e distribuição eletrônica\nHund?", "em orbitais de mesma energia, coloque 1 elétron em cada (mesmo spin) antes de emparelhar.", "frente-1/atomo"], ["a-frente-1", "Tabela periódica\nMetais alcalinos\n(Grupo, Características)", "Grupo: 1 (1A) · Características: Li, Na, K, Rb, Cs, Fr; reagem violentamente com água, formam M⁺.", "frente-1/tabela-ligacoes"], ["a-frente-1", "Tabela periódica\nAlcalinoterrosos\n(Grupo, Características)", "Grupo: 2 (2A) · Características: Be, Mg, Ca, Sr, Ba, Ra; formam M²⁺.", "frente-1/tabela-ligacoes"], ["a-frente-1", "Tabela periódica\nFamília do boro / carbono / nitrogênio\n(Grupo, Características)", "Grupo: 13 / 14 / 15 · Características: Al, C, Si, N, P...", "frente-1/tabela-ligacoes"], ["a-frente-1", "Tabela periódica\nCalcogênios\n(Grupo, Características)", "Grupo: 16 (6A) · Características: O, S, Se, Te; formam X²⁻.", "frente-1/tabela-ligacoes"], ["a-frente-1", "Tabela periódica\nHalogênios\n(Grupo, Características)", "Grupo: 17 (7A) · Características: F, Cl, Br, I, At; formam X⁻. Br₂ é líquido; F₂ e Cl₂ são gases.", "frente-1/tabela-ligacoes"], ["a-frente-1", "Tabela periódica\nGases nobres\n(Grupo, Características)", "Grupo: 18 · Características: He, Ne, Ar, Kr, Xe, Rn; valência completa (He: 2 e⁻; os outros: 8), muito pouco reativos.", "frente-1/tabela-ligacoes"], ["a-frente-1", "Tabela periódica\nRaio atômico?", "aumenta com o nº de camadas (para baixo) e, no período, diminui com o aumento da carga nuclear (para a direita).", "frente-1/tabela-ligacoes"], ["a-frente-1", "Tabela periódica\nEnergia de ionização (EI)?", "energia para retirar um elétron de um átomo gasoso. Cresce para cima e para a direita. Sempre EI₁ < EI₂ < EI₃...; há um salto grande quando se começa a retirar elétrons de uma camada interna.", "frente-1/tabela-ligacoes"], ["a-frente-1", "Tabela periódica\nAfinidade eletrônica?", "energia liberada ao receber um elétron (maior nos halogênios). Eletronegatividade: tendência de atrair elétrons numa ligação; F (4,0) > O > N, Cl > Br > C... Gases nobres não têm.", "frente-1/tabela-ligacoes"], ["a-frente-1", "Tabela periódica\nEletropositividade e reatividade de metais?", "crescem para baixo e para a esquerda (Cs, Fr). Reatividade de ametais: cresce para cima e para a direita (F).", "frente-1/tabela-ligacoes"], ["a-frente-1", "Tabela periódica\nRaio de íons?", "cátion < átomo < ânion. Em isoeletrônicos, quanto maior o Z, menor o raio : O²⁻ > F⁻ > Na⁺ > Mg²⁺.", "frente-1/tabela-ligacoes"], ["a-frente-1", "Ligações químicas\nEntre\n(Iônica, Covalente, Metálica)", "Iônica: metal + ametal (ou H) · Covalente: ametal + ametal, ametal + H · Metálica: metal + metal", "frente-1/tabela-ligacoes"], ["a-frente-1", "Ligações químicas\nMecanismo\n(Iônica, Covalente, Metálica)", "Iônica: transferência de elétrons: cátion e ânion atraem-se · Covalente: compartilhamento de pares de elétrons · Metálica: cátions em um \"mar\" de elétrons livres", "frente-1/tabela-ligacoes"], ["a-frente-1", "Ligações químicas\nEstado (25 °C)\n(Iônica, Covalente, Metálica)", "Iônica: sólidos cristalinos · Covalente: gases, líquidos, sólidos moleculares; ou reticulares · Metálica: sólidos (exceto Hg)", "frente-1/tabela-ligacoes"], ["a-frente-1", "Ligações químicas\nCondutividade\n(Iônica, Covalente, Metálica)", "Iônica: só fundido ou em solução (íons livres) · Covalente: não conduz (exceto grafite e ácidos em água) · Metálica: conduz no estado sólido", "frente-1/tabela-ligacoes"], ["a-frente-1", "Ligações químicas\nOutras\n(Iônica, Covalente, Metálica)", "Iônica: duros, quebradiços, muitos solúveis em água · Covalente: moleculares: macios · Metálica: maleáveis, dúcteis, brilho", "frente-1/tabela-ligacoes"], ["a-frente-1", "Ligações químicas\nIônico\n(Partículas e ligação, Exemplos)", "Partículas e ligação: íons; atração eletrostática · Exemplos: NaCl, CaO", "frente-1/tabela-ligacoes"], ["a-frente-1", "Ligações químicas\nMolecular\n(Partículas e ligação, Exemplos)", "Partículas e ligação: moléculas; forças intermoleculares · Exemplos: gelo, I₂, açúcar", "frente-1/tabela-ligacoes"], ["a-frente-1", "Ligações químicas\nCovalente (reticular)\n(Partículas e ligação, Exemplos)", "Partículas e ligação: rede de ligações covalentes · Exemplos: diamante, grafite, SiO₂, SiC", "frente-1/tabela-ligacoes"], ["a-frente-1", "Ligações químicas\nMetálico\n(Partículas e ligação, Exemplos)", "Partículas e ligação: cátions e elétrons livres · Exemplos: Fe, Cu, Na", "frente-1/tabela-ligacoes"], ["a-frente-1", "Ligações químicas\nSimples?", "(1 par: 1σ), dupla (2 pares: 1σ + 1π) e tripla (3 pares: 1σ + 2π). Quanto maior a ordem da ligação, menor o comprimento e maior a energia : C≡C > C=C > C–C em energia.", "frente-1/tabela-ligacoes"], ["a-frente-1", "Ligações químicas\nPolar?", "entre átomos de eletronegatividades diferentes (δ⁺ e δ⁻). Apolar : átomos iguais (H₂, O₂, Cl₂).", "frente-1/tabela-ligacoes"], ["a-frente-1", "Ligações químicas\nDativa (coordenada)?", "o par compartilhado vem de apenas um dos átomos (que ainda tem par livre, e o outro precisa de par). Ex.: SO₂, SO₃, O₃, NH₄⁺, H₃O⁺, CO.", "frente-1/tabela-ligacoes"], ["a-frente-1", "Ligações químicas\nRessonância?", "quando uma única fórmula de Lewis não descreve a molécula (O₃, SO₂, CO₃²⁻, benzeno); as ligações são equivalentes, intermediárias entre simples e dupla.", "frente-1/tabela-ligacoes"], ["a-frente-1", "Geometria molecular e polaridade\nApolares?", "geometria simétrica com ligantes iguais: CO₂, BF₃, CH₄, CCl₄, SO₃, PCl₅ e, claro, as substâncias simples (H₂, O₂).", "frente-1/tabela-ligacoes"], ["a-frente-1", "Geometria molecular e polaridade\nPolares?", "H₂O, NH₃, SO₂, HCl, CH₃Cl, CHCl₃, O₃ (levemente). Regra prática: se há pares livres no central, ou ligantes diferentes, é polar.", "frente-1/tabela-ligacoes"], ["a-frente-1", "Forças intermoleculares e propriedades físicas\nDipolo induzido (London, dispersão)\n(Onde ocorre, Intensidade)", "Onde ocorre: todas as moléculas; única nas apolares (O₂, CH₄, I₂) · Intensidade: fraca; cresce com o tamanho/massa e a área de contato", "frente-1/tabela-ligacoes"], ["a-frente-1", "Forças intermoleculares e propriedades físicas\nDipolo permanente (dipolo-dipolo)\n(Onde ocorre, Intensidade)", "Onde ocorre: moléculas polares (HCl, CH₃Cl) · Intensidade: média", "frente-1/tabela-ligacoes"], ["a-frente-1", "Forças intermoleculares e propriedades físicas\nLigação de hidrogênio\n(Onde ocorre, Intensidade)", "Onde ocorre: H ligado a F, O ou N (H₂O, NH₃, HF, álcoois, ácidos) · Intensidade: a mais forte das três", "frente-1/tabela-ligacoes"], ["a-frente-1", "Forças intermoleculares e propriedades físicas\nÍon-dipolo\n(Onde ocorre, Intensidade)", "Onde ocorre: íons dissolvidos em água · Intensidade: explica a dissolução de sais", "frente-1/tabela-ligacoes"], ["a-frente-1", "Forças intermoleculares e propriedades físicas\nPonto de ebulição anômalo?", "H₂O (100 °C) ferve muito acima de H₂S (≈ −60 °C), pois a água faz ligações de hidrogênio; o mesmo vale para HF e NH₃ em relação às suas famílias. Nos demais hidretos (CH₄, SiH₄, GeH₄, HCl, HBr, HI) o PE cresce com a massa.", "frente-1/tabela-ligacoes"], ["a-frente-1", "Forças intermoleculares e propriedades físicas\nGelo?", "as ligações de hidrogênio formam uma estrutura aberta e hexagonal, por isso o gelo é menos denso que a água líquida (boia).", "frente-1/tabela-ligacoes"], ["a-frente-1", "Forças intermoleculares e propriedades físicas\nSolubilidade?", "\"semelhante dissolve semelhante\". Polar dissolve polar e iônico (água dissolve NaCl, etanol, açúcar); apolar dissolve apolar (óleo e gasolina). Água e óleo não se misturam.", "frente-1/tabela-ligacoes"], ["a-frente-1", "Forças intermoleculares e propriedades físicas\nRamificação?", "entre isômeros, o ramificado tem PE menor (menor área de contato).", "frente-1/tabela-ligacoes"], ["a-frente-1", "Radioatividade\nFissão nuclear?", "núcleo pesado, bombardeado por nêutron, divide-se e libera muita energia e mais nêutrons (reação em cadeia). ²³⁵U + ¹n → ¹⁴¹Ba + ⁹²Kr + 3 ¹n. Usada em usinas (Angra) e bombas atômicas. Gera rejeitos radioativos.", "frente-1/atomo"], ["a-frente-1", "Radioatividade\nFusão nuclear?", "núcleos leves se unem, liberando mais energia por massa que a fissão; ocorre no Sol e nas bombas de hidrogênio. ²H + ³H → ⁴He + ¹n. Exige temperaturas altíssimas.", "frente-1/atomo"], ["a-frente-1", "Radioatividade\nCarbono-14?", "(P ≈ 5730 anos): datação de fósseis e objetos orgânicos de até cerca de 50 mil anos.", "frente-1/atomo"], ["a-frente-1", "Radioatividade\nIodo-131?", "diagnóstico e tratamento da tireoide. Cobalto-60: radioterapia e esterilização. Tecnécio-99m: exames de imagem.", "frente-1/atomo"], ["a-frente-2", "Matéria e suas transformações\nSubstância simples\n(Definição, Exemplos)", "Definição: um só elemento · Exemplos: O₂, O₃, H₂, C (grafite), Fe", "frente-2/materia-estequiometria"], ["a-frente-2", "Matéria e suas transformações\nSubstância composta\n(Definição, Exemplos)", "Definição: 2 ou mais elementos, proporção fixa · Exemplos: H₂O, CO₂, NaCl", "frente-2/materia-estequiometria"], ["a-frente-2", "Matéria e suas transformações\nMistura homogênea (solução)\n(Definição, Exemplos)", "Definição: 1 fase, aspecto uniforme · Exemplos: ar filtrado, água salgada, álcool 96%, ligas", "frente-2/materia-estequiometria"], ["a-frente-2", "Matéria e suas transformações\nMistura heterogênea\n(Definição, Exemplos)", "Definição: 2 ou mais fases · Exemplos: água + óleo, granito, água + gelo (1 só componente, 2 fases)", "frente-2/materia-estequiometria"], ["a-frente-2", "Matéria e suas transformações\nsólido + sólido (tamanhos diferentes)\n(Método, Princípio)", "Método: peneiração (tamisação) · Princípio: tamanho das partículas", "frente-2/materia-estequiometria"], ["a-frente-2", "Matéria e suas transformações\nsólido magnético + outro\n(Método, Princípio)", "Método: separação magnética · Princípio: ferro é atraído por ímã", "frente-2/materia-estequiometria"], ["a-frente-2", "Matéria e suas transformações\nsólidos de densidades diferentes\n(Método, Princípio)", "Método: levigação; flotação · Princípio: corrente de água; densidade em líquido", "frente-2/materia-estequiometria"], ["a-frente-2", "Matéria e suas transformações\nsólidos com solubilidades diferentes\n(Método, Princípio)", "Método: dissolução fracionada · Princípio: só um se dissolve (areia + sal)", "frente-2/materia-estequiometria"], ["a-frente-2", "Matéria e suas transformações\nsólido + sólido, um sublima\n(Método, Princípio)", "Método: sublimação · Princípio: iodo + areia", "frente-2/materia-estequiometria"], ["a-frente-2", "Matéria e suas transformações\nsólido + líquido (heterogênea)\n(Método, Princípio)", "Método: decantação, centrifugação, filtração · Princípio: densidade; força centrífuga; filtro retém o sólido", "frente-2/materia-estequiometria"], ["a-frente-2", "Matéria e suas transformações\nlíquido + líquido imiscíveis\n(Método, Princípio)", "Método: decantação (funil de bromo) · Princípio: densidade (óleo + água)", "frente-2/materia-estequiometria"], ["a-frente-2", "Matéria e suas transformações\nsólido dissolvido + líquido\n(Método, Princípio)", "Método: evaporação; cristalização; destilação simples · Princípio: só o líquido vaporiza (salinas; água pura)", "frente-2/materia-estequiometria"], ["a-frente-2", "Matéria e suas transformações\nlíquido + líquido miscíveis\n(Método, Princípio)", "Método: destilação fracionada · Princípio: pontos de ebulição diferentes (petróleo; etanol + água)", "frente-2/materia-estequiometria"], ["a-frente-2", "Matéria e suas transformações\ngás + gás\n(Método, Princípio)", "Método: liquefação fracionada · Princípio: ar líquido: N₂ (PE −196 °C), O₂ (−183 °C)", "frente-2/materia-estequiometria"], ["a-frente-2", "Leis ponderais, mol e massas\nMassa atômica\n(Definição)", "Definição: em u (1 u = 1/12 do ¹²C). Valores: H 1; C 12; N 14; O 16; Na 23; Mg 24; Al 27; S 32; Cl 35,5; K 39; Ca 40; Fe 56; Cu 63,5; Ag 108.", "frente-2/materia-estequiometria"], ["a-frente-2", "Leis ponderais, mol e massas\nMassa molecular / molar (M)\n(Definição)", "Definição: soma das massas atômicas; M em g/mol. M(H₂O) = 18; M(CO₂) = 44; M(H₂SO₄) = 98.", "frente-2/materia-estequiometria"], ["a-frente-2", "Leis ponderais, mol e massas\nMol\n(Definição)", "Definição: 6,02·10²³ entidades (constante de Avogadro). n = m/M.", "frente-2/materia-estequiometria"], ["a-frente-2", "Leis ponderais, mol e massas\nVolume molar\n(Definição)", "Definição: CNTP (273 K, 1 atm): 22,4 L/mol . 25 °C e 1 atm: ≈ 24,5 L/mol. (IUPAC atual: 273,15 K e 100 kPa: ≈ 22,7 L/mol.)", "frente-2/materia-estequiometria"], ["a-frente-2", "Leis ponderais, mol e massas\nLavoisier (conservação das massas)?", "num sistema fechado, massa dos reagentes = massa dos produtos.", "frente-2/materia-estequiometria"], ["a-frente-2", "Leis ponderais, mol e massas\nProust (proporções definidas)?", "uma substância sempre tem a mesma proporção em massa entre os elementos. Água: 2 g de H para 16 g de O (1 : 8). Com 4 g de H e 16 g de O, sobram 2 g de H.", "frente-2/materia-estequiometria"], ["a-frente-2", "Leis ponderais, mol e massas\nDalton (proporções múltiplas)?", "variando a massa de um elemento que se combina com massa fixa do outro, as massas do primeiro estão em razão de números inteiros e pequenos. CO (12 g C : 16 g O) e CO₂ (12 g C : 32 g O): a razão do O é 1 : 2.", "frente-2/materia-estequiometria"], ["a-frente-2", "Leis ponderais, mol e massas\nGay-Lussac (volumes)?", "gases que reagem à mesma T e P têm volumes em razão de números inteiros pequenos (2 H₂ + O₂: 2 volumes para 1).", "frente-2/materia-estequiometria"], ["a-frente-2", "Estequiometria\nPercentual?", "% de cada elemento na massa molar. Mínima: menor proporção inteira. Molecular: fórmula mínima × n, com n = M molecular ÷ M da mínima.", "frente-2/materia-estequiometria"], ["a-frente-2", "Gases\nIsotérmica\n(Constante, Lei)", "Constante: T · Lei: P₁V₁ = P₂V₂ (inversamente proporcionais)", "frente-2/gases-solucoes"], ["a-frente-2", "Gases\nIsobárica\n(Constante, Lei)", "Constante: P · Lei: V₁/T₁ = V₂/T₂", "frente-2/gases-solucoes"], ["a-frente-2", "Gases\nIsocórica (isovolumétrica)\n(Constante, Lei)", "Constante: V · Lei: P₁/T₁ = P₂/T₂", "frente-2/gases-solucoes"], ["a-frente-2", "Gases\nGeral\n(Constante, Lei)", "Constante: n · Lei: P₁V₁/T₁ = P₂V₂/T₂", "frente-2/gases-solucoes"], ["a-frente-2", "Gases\nGraham?", "v₁/v₂ = √(M₂/M₁). H₂ (M = 2) e O₂ (M = 32): √(32/2) = 4, ou seja, o H₂ se difunde 4 vezes mais rápido .", "frente-2/gases-solucoes"], ["a-frente-2", "Soluções\nComum (C)\n(Fórmula, Unidade)", "Fórmula: m₁/V · Unidade: g/L", "frente-2/gases-solucoes"], ["a-frente-2", "Soluções\nDensidade (d)\n(Fórmula, Unidade)", "Fórmula: m (solução)/V · Unidade: g/mL", "frente-2/gases-solucoes"], ["a-frente-2", "Soluções\nMolaridade (M)\n(Fórmula, Unidade)", "Fórmula: n₁/V = m₁/(M₁·V) · Unidade: mol/L", "frente-2/gases-solucoes"], ["a-frente-2", "Soluções\nTítulo (τ)\n(Fórmula, Unidade)", "Fórmula: m₁/m (× 100 = %) · Unidade: adimensional", "frente-2/gases-solucoes"], ["a-frente-2", "Soluções\nFração molar (x)\n(Fórmula, Unidade)", "Fórmula: n₁/n total (Σx = 1) · Unidade: adimensional", "frente-2/gases-solucoes"], ["a-frente-2", "Soluções\nMolalidade (W)\n(Fórmula, Unidade)", "Fórmula: n₁/m₂ (kg de solvente) · Unidade: mol/kg", "frente-2/gases-solucoes"], ["a-frente-2", "Soluções\nppm\n(Fórmula, Unidade)", "Fórmula: mg de soluto/kg de solução (ou mg/L em água diluída) · Unidade: ppm", "frente-2/gases-solucoes"], ["a-frente-2", "Soluções\nDiluição?", "M₁V₁ = M₂V₂ (o nº de mols de soluto não muda). 100 mL de 2 mol/L até 500 mL: M₂ = 2 × 100/500 = 0,4 mol/L (adicionam-se 400 mL de água).", "frente-2/gases-solucoes"], ["a-frente-2", "Soluções\nMistura do mesmo soluto, sem reação?", "M₁V₁ + M₂V₂ = M_f·V_f. 200 mL de NaCl 1 mol/L + 300 mL de 2 mol/L: M_f = (0,2 + 0,6)/0,5 = 1,6 mol/L .", "frente-2/gases-solucoes"], ["a-frente-2", "Propriedades coligativas\nTonoscopia\n(O que acontece, Expressão)", "O que acontece: pressão de vapor do solvente diminui · Expressão: Raoult: p = p°·x_solvente", "frente-2/gases-solucoes"], ["a-frente-2", "Propriedades coligativas\nEbulioscopia\n(O que acontece, Expressão)", "O que acontece: ponto de ebulição aumenta · Expressão: Δt_e = K_e·W·i", "frente-2/gases-solucoes"], ["a-frente-2", "Propriedades coligativas\nCrioscopia\n(O que acontece, Expressão)", "O que acontece: ponto de congelamento diminui · Expressão: Δt_c = K_c·W·i", "frente-2/gases-solucoes"], ["a-frente-2", "Propriedades coligativas\nOsmose\n(O que acontece, Expressão)", "O que acontece: solvente passa pela membrana semipermeável do meio menos concentrado para o mais concentrado · Expressão: π = M·R·T·i", "frente-2/gases-solucoes"], ["a-frente-2", "Oxirredução\nSubstância simples (O₂, Fe, S₈)\n(NOX)", "NOX: 0", "frente-2/gases-solucoes"], ["a-frente-2", "Oxirredução\nÍon monoatômico\n(NOX)", "NOX: igual à carga (Fe³⁺: +3)", "frente-2/gases-solucoes"], ["a-frente-2", "Oxirredução\nSoma dos NOX\n(NOX)", "NOX: molécula: 0; íon composto: igual à carga", "frente-2/gases-solucoes"], ["a-frente-2", "Oxirredução\n1A (alcalinos) e Ag\n(NOX)", "NOX: +1", "frente-2/gases-solucoes"], ["a-frente-2", "Oxirredução\n2A (alcalinoterrosos) e Zn\n(NOX)", "NOX: +2", "frente-2/gases-solucoes"], ["a-frente-2", "Oxirredução\nHalogênios\n(NOX)", "NOX: −1 quando são o elemento mais eletronegativo; F é sempre −1", "frente-2/gases-solucoes"], ["a-frente-2", "Oxirredução\nCalcogênios (S, Se)\n(NOX)", "NOX: −2 em compostos binários", "frente-2/gases-solucoes"], ["a-frente-2", "Oxirredução\nCruze?", "os Δ: o Δ da oxidação vira o coeficiente da substância que reduz, e vice-versa.", "frente-2/gases-solucoes"], ["a-frente-2", "Oxirredução\nAutorredox (desproporcionamento)?", "o mesmo elemento oxida e reduz. Cl₂ + 2 NaOH → NaCl + NaClO + H₂O (Cl: 0 → −1 e +1). 2 H₂O₂ → 2 H₂O + O₂ (O: −1 → −2 e 0).", "frente-2/gases-solucoes"], ["a-frente-2", "Oxirredução\nOxidantes comuns?", "O₂, O₃, halogênios, H₂O₂, KMnO₄, K₂Cr₂O₇, HNO₃, HClO. Redutores: metais (K, Na, Ca, Mg, Zn, Fe), H₂, CO, C, SO₂, Fe²⁺.", "frente-2/gases-solucoes"], ["a-frente-2", "Oxirredução\nCotidiano?", "combustão e respiração (oxidam compostos de carbono); enferrujamento do ferro; escurecimento de maçã cortada; branqueamento (NaClO); fotossíntese (redução do CO₂); bafômetro: o etanol é oxidado e o dicromato (alaranjado, Cr⁶⁺) vira Cr³⁺ (verde).", "frente-2/gases-solucoes"], ["a-frente-3", "Termoquímica\nCalor\n(Exotérmico, Endotérmico)", "Exotérmico: liberado para o ambiente · Endotérmico: absorvido do ambiente", "frente-3/termo-cinetica"], ["a-frente-3", "Termoquímica\nH dos produtos\n(Exotérmico, Endotérmico)", "Exotérmico: menor que a dos reagentes · Endotérmico: maior que a dos reagentes", "frente-3/termo-cinetica"], ["a-frente-3", "Termoquímica\nExemplos\n(Exotérmico, Endotérmico)", "Exotérmico: combustões, condensação, solidificação, neutralização, dissolução de NaOH · Endotérmico: fusão, vaporização, fotossíntese, decomposição do CaCO₃, dissolução do NH₄NO₃", "frente-3/termo-cinetica"], ["a-frente-3", "Termoquímica\nFormação?", "1 mol de substância formado a partir de substâncias simples mais estáveis. Essas substâncias simples têm ΔH = 0: H₂(g), O₂(g), N₂(g), C(grafite), S(rômbico), Fe(s), Hg(l), etc.", "frente-3/termo-cinetica"], ["a-frente-3", "Termoquímica\nCombustão?", "1 mol de combustível queimado com O₂ (sempre exotérmico). Neutralização: 1 mol de H₂O formado de H⁺ + OH⁻ (≈ −57 kJ/mol para ácido forte e base forte). Dissolução e mudança de estado .", "frente-3/termo-cinetica"], ["a-frente-3", "Cinética química\nTemperatura ↑\n(Efeito, Por quê)", "Efeito: velocidade ↑ (regra empírica: a cada +10 °C, dobra ou triplica) · Por quê: mais moléculas com energia ≥ Eₐ e mais colisões", "frente-3/termo-cinetica"], ["a-frente-3", "Cinética química\nConcentração ↑ (pressão ↑ em gases)\n(Efeito, Por quê)", "Efeito: velocidade ↑ · Por quê: mais colisões por tempo", "frente-3/termo-cinetica"], ["a-frente-3", "Cinética química\nSuperfície de contato ↑ (sólido pulverizado)\n(Efeito, Por quê)", "Efeito: velocidade ↑ · Por quê: mais partículas expostas", "frente-3/termo-cinetica"], ["a-frente-3", "Cinética química\nCatalisador\n(Efeito, Por quê)", "Efeito: velocidade ↑ · Por quê: caminho alternativo com Eₐ menor; é regenerado no final; não muda ΔH nem o rendimento", "frente-3/termo-cinetica"], ["a-frente-3", "Cinética química\nInibidor / veneno\n(Efeito, Por quê)", "Efeito: velocidade ↓ · Por quê: aumenta Eₐ ou bloqueia o catalisador", "frente-3/termo-cinetica"], ["a-frente-3", "Equilíbrio químico\nInício\n(N₂O₄, NO₂)", "N₂O₄: 1,0 · NO₂: 0", "frente-3/equilibrio"], ["a-frente-3", "Equilíbrio químico\nReage/forma\n(N₂O₄, NO₂)", "N₂O₄: −0,2 · NO₂: +0,4", "frente-3/equilibrio"], ["a-frente-3", "Equilíbrio químico\nEquilíbrio\n(N₂O₄, NO₂)", "N₂O₄: 0,8 · NO₂: 0,4", "frente-3/equilibrio"], ["a-frente-3", "Equilíbrio químico\nAdicionar reagente\n(Desloca para, K muda?)", "Desloca para: produtos (consome o adicionado) · K muda?: não", "frente-3/equilibrio"], ["a-frente-3", "Equilíbrio químico\nRetirar produto\n(Desloca para, K muda?)", "Desloca para: produtos (repõe o retirado) · K muda?: não", "frente-3/equilibrio"], ["a-frente-3", "Equilíbrio químico\nAumentar a pressão (diminuir volume)\n(Desloca para, K muda?)", "Desloca para: lado com menos mols gasosos · K muda?: não", "frente-3/equilibrio"], ["a-frente-3", "Equilíbrio químico\nAumentar a temperatura\n(Desloca para, K muda?)", "Desloca para: sentido endotérmico · K muda?: sim", "frente-3/equilibrio"], ["a-frente-3", "Equilíbrio químico\nCatalisador\n(Desloca para, K muda?)", "Desloca para: não desloca; só chega mais rápido · K muda?: não", "frente-3/equilibrio"], ["a-frente-3", "Equilíbrio químico\nGás inerte a volume constante\n(Desloca para, K muda?)", "Desloca para: não desloca · K muda?: não", "frente-3/equilibrio"], ["a-frente-3", "Equilíbrio químico\nK ≫ 1?", "no equilíbrio há mais produtos. K ≪ 1: mais reagentes. K não diz a velocidade.", "frente-3/equilibrio"], ["a-frente-3", "Equilíbrio iônico\nácido forte + base forte\n(pH da solução, Exemplo)", "pH da solução: 7 (não hidrolisa) · Exemplo: NaCl", "frente-3/equilibrio"], ["a-frente-3", "Equilíbrio iônico\nácido forte + base fraca\n(pH da solução, Exemplo)", "pH da solução: < 7: NH₄⁺ + H₂O ⇌ NH₃ + H₃O⁺ · Exemplo: NH₄Cl", "frente-3/equilibrio"], ["a-frente-3", "Equilíbrio iônico\nácido fraco + base forte\n(pH da solução, Exemplo)", "pH da solução: > 7: CH₃COO⁻ + H₂O ⇌ CH₃COOH + OH⁻ · Exemplo: CH₃COONa, Na₂CO₃", "frente-3/equilibrio"], ["a-frente-3", "Equilíbrio iônico\nácido fraco + base fraca\n(pH da solução, Exemplo)", "pH da solução: depende de Ka e Kb · Exemplo: NH₄CN", "frente-3/equilibrio"], ["a-frente-3", "Eletroquímica: pilhas\nÂnodo?", "oxidação, polo − , perde massa (se for metal). Cátodo: redução, polo + . Elétrons: ânodo → cátodo (fio). Ponte salina: fecha o circuito e mantém a neutralidade, com íons migrando (ânions para o ânodo, cátions para o cátodo).", "frente-3/eletroquimica"], ["a-frente-3", "Eletroquímica: pilhas\nNotação?", "Zn | Zn²⁺ ‖ Cu²⁺ | Cu (ânodo à esquerda, ‖ = ponte salina).", "frente-3/eletroquimica"], ["a-frente-3", "Eletroquímica: pilhas\nΔE° = E° red (cátodo) − E° red (ânodo)?", "> 0 para pilha. O que tem maior E°red sofre redução. Não multiplique o E° pelos coeficientes.", "frente-3/eletroquimica"], ["a-frente-3", "Eletroquímica: pilhas\nPilha seca comum (Leclanché)?", "ânodo de Zn, cátodo de grafite com MnO₂. Alcalina: meio básico (KOH), dura mais.", "frente-3/eletroquimica"], ["a-frente-3", "Eletroquímica: pilhas\nBateria de chumbo (carro)?", "Pb (ânodo), PbO₂ (cátodo) e H₂SO₄(aq); recarregável (a recarga é uma eletrólise); cada célula dá ≈ 2 V (6 células = 12 V).", "frente-3/eletroquimica"], ["a-frente-3", "Eletroquímica: pilhas\nÍon-lítio?", "recarregável, leve, usada em celulares. Célula a combustível H₂/O₂: ânodo H₂ → 2H⁺ + 2e⁻; cátodo O₂ + 4H⁺ + 4e⁻ → 2H₂O; o produto é água.", "frente-3/eletroquimica"], ["a-frente-3", "Eletrólise\nReação\n(Pilha, Eletrólise)", "Pilha: espontânea · Eletrólise: forçada", "frente-3/eletroquimica"], ["a-frente-3", "Eletrólise\nEnergia\n(Pilha, Eletrólise)", "Pilha: química → elétrica · Eletrólise: elétrica → química", "frente-3/eletroquimica"], ["a-frente-3", "Eletrólise\nÂnodo\n(Pilha, Eletrólise)", "Pilha: − (oxidação) · Eletrólise: + (oxidação)", "frente-3/eletroquimica"], ["a-frente-3", "Eletrólise\nCátodo\n(Pilha, Eletrólise)", "Pilha: + (redução) · Eletrólise: − (redução)", "frente-3/eletroquimica"], ["a-frente-3", "Eletrólise\nNaCl(aq)\n(Cátodo (−), Ânodo (+), Resultado)", "Cátodo (−): 2H₂O + 2e⁻ → H₂ + 2OH⁻ · Ânodo (+): 2Cl⁻ → Cl₂ + 2e⁻ · Resultado: H₂, Cl₂ e NaOH na solução (indústria cloro-soda)", "frente-3/eletroquimica"], ["a-frente-3", "Eletrólise\nCuSO₄(aq)\n(Cátodo (−), Ânodo (+), Resultado)", "Cátodo (−): Cu²⁺ + 2e⁻ → Cu · Ânodo (+): 2H₂O → O₂ + 4H⁺ + 4e⁻ · Resultado: Cu(s), O₂; solução fica ácida (H₂SO₄)", "frente-3/eletroquimica"], ["a-frente-3", "Eletrólise\nCuCl₂(aq)\n(Cátodo (−), Ânodo (+), Resultado)", "Cátodo (−): Cu²⁺ + 2e⁻ → Cu · Ânodo (+): 2Cl⁻ → Cl₂ + 2e⁻ · Resultado: Cu e Cl₂", "frente-3/eletroquimica"], ["a-frente-3", "Eletrólise\nCátions?", "metais comuns (Zn²⁺, Fe²⁺, Cu²⁺, Ag⁺...) > H⁺ > 1A, 2A, Al³⁺. Se o cátion é de 1A, 2A ou Al³⁺, reduz a água : 2H₂O + 2e⁻ → H₂ + 2OH⁻.", "frente-3/eletroquimica"], ["a-frente-3", "Eletrólise\nÂnions?", "não oxigenados (Cl⁻, Br⁻, I⁻, S²⁻) > OH⁻ > oxigenados (SO₄²⁻, NO₃⁻, CO₃²⁻) e F⁻. Se o ânion é oxigenado ou F⁻, oxida a água : 2H₂O → O₂ + 4H⁺ + 4e⁻.", "frente-3/eletroquimica"], ["a-frente-4", "Conceitos de ácido e base\nArrhenius\n(Ácido, Base, Alcance)", "Ácido: em água, libera H⁺ (H₃O⁺) como único cátion · Base: em água, libera OH⁻ como único ânion · Alcance: só soluções aquosas", "frente-4/inorganica"], ["a-frente-4", "Conceitos de ácido e base\nBrønsted-Lowry\n(Ácido, Base, Alcance)", "Ácido: doa H⁺ · Base: recebe H⁺ · Alcance: qualquer solvente; define pares conjugados", "frente-4/inorganica"], ["a-frente-4", "Conceitos de ácido e base\nLewis\n(Ácido, Base, Alcance)", "Ácido: recebe par de elétrons · Base: doa par de elétrons · Alcance: mais geral: nem precisa de H", "frente-4/inorganica"], ["a-frente-4", "Ácidos\nhipocloroso\n(Fórmula, Outros, Fórmula)", "Fórmula: HClO · Outros: nítrico / nitroso · Fórmula: HNO₃ / HNO₂", "frente-4/inorganica"], ["a-frente-4", "Ácidos\ncloroso\n(Fórmula, Outros, Fórmula)", "Fórmula: HClO₂ · Outros: sulfúrico / sulfuroso · Fórmula: H₂SO₄ / H₂SO₃", "frente-4/inorganica"], ["a-frente-4", "Ácidos\nclórico\n(Fórmula, Outros, Fórmula)", "Fórmula: HClO₃ · Outros: fosfórico / fosforoso · Fórmula: H₃PO₄ / H₃PO₃", "frente-4/inorganica"], ["a-frente-4", "Ácidos\nperclórico\n(Fórmula, Outros, Fórmula)", "Fórmula: HClO₄ · Outros: carbônico; bórico · Fórmula: H₂CO₃; H₃BO₃", "frente-4/inorganica"], ["a-frente-4", "Ácidos\nHidrácidos?", "fortes: HCl, HBr, HI. Moderado: HF. Fracos: H₂S, HCN e demais.", "frente-4/inorganica"], ["a-frente-4", "Ácidos\nOxiácidos?", "(nº de O − nº de H ionizáveis): 0 fraco (H₃BO₃, HClO); 1 moderado (H₃PO₄, H₂SO₃, HNO₂); ≥ 2 forte (H₂SO₄, HNO₃, HClO₄, HMnO₄). Exceção: H₂CO₃ (pela regra seria moderado) é fraco e instável.", "frente-4/inorganica"], ["a-frente-4", "Ácidos\nH₂SO₄?", "o mais produzido pela indústria; baterias de chumbo, fertilizantes; desidratante e corrosivo. HNO₃: fertilizantes e explosivos. HCl: suco gástrico (≈ pH 1–2), limpeza (\"ácido muriático\"). H₃PO₄: refrigerantes de cola, fertilizantes. HF: corrói o vidro. H₂CO₃: refrigerantes e água com gás.", "frente-4/inorganica"], ["a-frente-4", "Bases (hidróxidos)\nNaOH\n(Nome popular, Uso)", "Nome popular: soda cáustica · Uso: sabão, desentupidor, papel, alumínio", "frente-4/inorganica"], ["a-frente-4", "Bases (hidróxidos)\nFortes e solúveis?", "1A (NaOH, KOH) totalmente dissociadas. 2A: Ca(OH)₂, Sr(OH)₂, Ba(OH)₂ fortes (pouco solúveis); Mg(OH)₂ e Be(OH)₂ fracas. Demais metais: pouco solúveis e fracos [Fe(OH)₃, Al(OH)₃, Cu(OH)₂]. Amônia: NH₃ + H₂O ⇌ NH₄⁺ + OH⁻ (base fraca e solúvel; \"NH₄OH\").", "frente-4/inorganica"], ["a-frente-4", "Sais\nClO⁻, ClO₃⁻, ClO₄⁻\n(Nome, Ânion, Nome)", "Nome: hipoclorito, clorato, perclorato · Ânion: MnO₄⁻ · Nome: permanganato", "frente-4/inorganica"], ["a-frente-4", "Sais\nNaCl\n(Nome popular / uso)", "Nome popular / uso: sal de cozinha, soro, conservante", "frente-4/inorganica"], ["a-frente-4", "Sais\nNaHCO₃\n(Nome popular / uso)", "Nome popular / uso: bicarbonato: antiácido, fermento, extintores", "frente-4/inorganica"], ["a-frente-4", "Sais\nCaCO₃\n(Nome popular / uso)", "Nome popular / uso: calcário, mármore, giz, conchas; cimento e cal", "frente-4/inorganica"], ["a-frente-4", "Sais\nCaSO₄·½H₂O / ·2H₂O\n(Nome popular / uso)", "Nome popular / uso: gesso / gipsita", "frente-4/inorganica"], ["a-frente-4", "Sais\nNaF\n(Nome popular / uso)", "Nome popular / uso: fluoretos: cremes dentais", "frente-4/inorganica"], ["a-frente-4", "Sais\nKNO₃, NaNO₃\n(Nome popular / uso)", "Nome popular / uso: salitre: pólvora, fertilizantes", "frente-4/inorganica"], ["a-frente-4", "Sais\nNormal?", "neutralização total (NaCl). Ácido (hidrogenossal): ainda tem H ionizável: NaHCO₃ (hidrogenocarbonato de sódio, \"bicarbonato\"), NaHSO₄. Básico (hidroxissal): tem OH⁻: Ca(OH)Cl. Duplo ou misto: dois cátions ou dois ânions (KNaSO₄; CaOCl₂). Hidratado: CuSO₄·5H₂O (sulfato de cobre II pentaidratado; azul; anidro é branco), CaSO₄·2H₂O (gipsita).", "frente-4/inorganica"], ["a-frente-4", "Sais\nSolúveis?", "sais de 1A e NH₄⁺; nitratos (NO₃⁻); acetatos; cloratos e percloratos.", "frente-4/inorganica"], ["a-frente-4", "Sais\nCloretos, brometos, iodetos?", "solúveis, exceto de Ag⁺, Pb²⁺, Hg₂²⁺. Sulfatos: solúveis, exceto Ca²⁺, Sr²⁺, Ba²⁺, Pb²⁺.", "frente-4/inorganica"], ["a-frente-4", "Sais\nCarbonatos, fosfatos, sulfetos, hidróxidos?", "insolúveis, exceto de 1A e NH₄⁺ (sulfetos e hidróxidos de 2A são solúveis ou pouco solúveis).", "frente-4/inorganica"], ["a-frente-4", "Óxidos\nBásico\n(Característica, Reações)", "Característica: metal 1A, 2A (NOX baixo) · Reações: Na₂O + H₂O → 2NaOH; CaO + H₂O → Ca(OH)₂; CaO + 2HCl → CaCl₂ + H₂O", "frente-4/inorganica"], ["a-frente-4", "Óxidos\nÁcido (anidrido)\n(Característica, Reações)", "Característica: ametal ou metal de NOX alto · Reações: SO₃ + H₂O → H₂SO₄; CO₂ + H₂O ⇌ H₂CO₃; CO₂ + Ca(OH)₂ → CaCO₃ + H₂O (turva a água de cal: teste do CO₂)", "frente-4/inorganica"], ["a-frente-4", "Óxidos\nAnfótero\n(Característica, Reações)", "Característica: ZnO, Al₂O₃, SnO, PbO, As₂O₃ · Reações: Al₂O₃ + 6HCl → 2AlCl₃ + 3H₂O; Al₂O₃ + 2NaOH → 2NaAlO₂ + H₂O", "frente-4/inorganica"], ["a-frente-4", "Óxidos\nNeutro (indiferente)\n(Característica, Reações)", "Característica: CO, NO, N₂O · Reações: não reagem com água, ácido ou base", "frente-4/inorganica"], ["a-frente-4", "Óxidos\nPeróxido\n(Característica, Reações)", "Característica: ânion O₂²⁻ (O: −1) · Reações: H₂O₂, Na₂O₂, CaO₂; Na₂O₂ + 2H₂O → 2NaOH + H₂O₂", "frente-4/inorganica"], ["a-frente-4", "Óxidos\nDuplo (misto)\n(Característica, Reações)", "Característica: soma de dois óxidos · Reações: Fe₃O₄ = FeO·Fe₂O₃ (magnetita)", "frente-4/inorganica"], ["a-frente-4", "Tipos de reação inorgânica\nSíntese (adição)\n(Esquema, Exemplos)", "Esquema: A + B → AB · Exemplos: 2Mg + O₂ → 2MgO; N₂ + 3H₂ → 2NH₃; CaO + H₂O → Ca(OH)₂", "frente-4/reacoes-polimeros"], ["a-frente-4", "Tipos de reação inorgânica\nDecomposição (análise)\n(Esquema, Exemplos)", "Esquema: AB → A + B · Exemplos: Pirólise (calor): CaCO₃ → CaO + CO₂; 2NaHCO₃ → Na₂CO₃ + CO₂ + H₂O. Fotólise (luz): 2AgBr → 2Ag + Br₂; 2H₂O₂ → 2H₂O + O₂. Eletrólise: 2H₂O → 2H₂ + O₂. Airbag: 2NaN₃ → 2Na + 3N₂.", "frente-4/reacoes-polimeros"], ["a-frente-4", "Tipos de reação inorgânica\nSimples troca (deslocamento)\n(Esquema, Exemplos)", "Esquema: A + BC → AC + B · Exemplos: Zn + CuSO₄ → ZnSO₄ + Cu; Cl₂ + 2NaBr → 2NaCl + Br₂", "frente-4/reacoes-polimeros"], ["a-frente-4", "Tipos de reação inorgânica\nDupla troca\n(Esquema, Exemplos)", "Esquema: AB + CD → AD + CB · Exemplos: BaCl₂ + Na₂SO₄ → BaSO₄↓ + 2NaCl; HCl + NaOH → NaCl + H₂O", "frente-4/reacoes-polimeros"], ["a-frente-4", "Tipos de reação inorgânica\nCombustão\n(Esquema, Exemplos)", "Esquema: combustível + O₂ · Exemplos: CH₄ + 2O₂ → CO₂ + 2H₂O", "frente-4/reacoes-polimeros"], ["a-frente-4", "Tipos de reação inorgânica\nNeutralização?", "ácido + base → sal + água. Total: H₂SO₄ + 2NaOH → Na₂SO₄ + 2H₂O. Parcial (sal ácido): H₂SO₄ + NaOH → NaHSO₄ + H₂O. Parcial (sal básico): Ca(OH)₂ + HCl → Ca(OH)Cl + H₂O.", "frente-4/reacoes-polimeros"], ["a-frente-4", "Polímeros\nPolietileno (PEAD, PEBD)\n(Monômero(s), Tipo, Usos)", "Monômero(s): eteno · Tipo: adição · Usos: sacolas, garrafas, tubos, brinquedos", "frente-4/reacoes-polimeros"], ["a-frente-4", "Polímeros\nPolipropileno (PP)\n(Monômero(s), Tipo, Usos)", "Monômero(s): propeno · Tipo: adição · Usos: embalagens, seringas, carpetes", "frente-4/reacoes-polimeros"], ["a-frente-4", "Polímeros\nPVC\n(Monômero(s), Tipo, Usos)", "Monômero(s): cloroeteno (cloreto de vinila) · Tipo: adição · Usos: tubos, conexões, cortinas", "frente-4/reacoes-polimeros"], ["a-frente-4", "Polímeros\nPoliestireno (PS)\n(Monômero(s), Tipo, Usos)", "Monômero(s): estireno (vinilbenzeno) · Tipo: adição · Usos: copos descartáveis; isopor (expandido)", "frente-4/reacoes-polimeros"], ["a-frente-4", "Polímeros\nTeflon (PTFE)\n(Monômero(s), Tipo, Usos)", "Monômero(s): tetrafluoroeteno · Tipo: adição · Usos: antiaderente, vedações", "frente-4/reacoes-polimeros"], ["a-frente-4", "Polímeros\nPoliacrilonitrila (orlon)\n(Monômero(s), Tipo, Usos)", "Monômero(s): acrilonitrila (CH₂=CH–CN) · Tipo: adição · Usos: fibras têxteis (\"lã sintética\")", "frente-4/reacoes-polimeros"], ["a-frente-4", "Polímeros\nPMMA (acrílico)\n(Monômero(s), Tipo, Usos)", "Monômero(s): metacrilato de metila · Tipo: adição · Usos: \"vidro orgânico\", lentes, aquários", "frente-4/reacoes-polimeros"], ["a-frente-4", "Polímeros\nPVA\n(Monômero(s), Tipo, Usos)", "Monômero(s): acetato de vinila · Tipo: adição · Usos: cola branca", "frente-4/reacoes-polimeros"], ["a-frente-4", "Polímeros\nBorracha natural\n(Monômero(s), Tipo, Usos)", "Monômero(s): isopreno (2-metilbuta-1,3-dieno) · Tipo: adição · Usos: do látex da seringueira; pneus", "frente-4/reacoes-polimeros"], ["a-frente-4", "Polímeros\nNeopreno\n(Monômero(s), Tipo, Usos)", "Monômero(s): cloropreno · Tipo: adição · Usos: luvas, roupas de mergulho", "frente-4/reacoes-polimeros"], ["a-frente-4", "Polímeros\nNáilon 6,6\n(Monômero(s), Tipo, Usos)", "Monômero(s): diácido + diamina · Tipo: condensação · Usos: fibras, cordas, engrenagens", "frente-4/reacoes-polimeros"], ["a-frente-4", "Polímeros\nPET\n(Monômero(s), Tipo, Usos)", "Monômero(s): ác. tereftálico + etilenoglicol · Tipo: condensação · Usos: garrafas, tecidos (poliéster)", "frente-4/reacoes-polimeros"], ["a-frente-4", "Polímeros\nBaquelite\n(Monômero(s), Tipo, Usos)", "Monômero(s): fenol + metanal · Tipo: condensação · Usos: cabos de panelas, tomadas", "frente-4/reacoes-polimeros"], ["a-frente-4", "Polímeros\nKevlar\n(Monômero(s), Tipo, Usos)", "Monômero(s): poliamida aromática · Tipo: condensação · Usos: coletes à prova de bala", "frente-4/reacoes-polimeros"], ["a-frente-4", "Polímeros\nTermoplásticos?", "amolecem com o calor e podem ser remoldados (PE, PP, PVC, PS, PET): recicláveis. Termofixos: endurecem com o calor e não amolecem de novo, pois têm ligações cruzadas (baquelite). Elastômeros: borrachas.", "frente-4/reacoes-polimeros"], ["a-frente-4", "Polímeros\nVulcanização (Goodyear)?", "aquecer a borracha natural com enxofre cria pontes S–S entre as cadeias, deixando-a mais resistente e elástica.", "frente-4/reacoes-polimeros"], ["a-frente-4", "Polímeros\nReciclagem?", "símbolos 1 PET, 2 PEAD, 3 PVC, 4 PEBD, 5 PP, 6 PS, 7 outros. A maioria dos plásticos não é biodegradável e persiste por décadas; alternativas: PLA e PHB (biodegradáveis), reciclagem e redução do uso.", "frente-4/reacoes-polimeros"], ["a-frente-4", "Aminoácidos e proteínas\nPrimária\n(O que é, Estabilizada por)", "O que é: sequência de aminoácidos · Estabilizada por: ligações peptídicas", "frente-4/bioquimica"], ["a-frente-4", "Aminoácidos e proteínas\nSecundária\n(O que é, Estabilizada por)", "O que é: α-hélice ou folha β · Estabilizada por: ligações de hidrogênio entre C=O e N–H", "frente-4/bioquimica"], ["a-frente-4", "Aminoácidos e proteínas\nTerciária\n(O que é, Estabilizada por)", "O que é: dobramento 3D de uma cadeia · Estabilizada por: interações entre cadeias laterais: pontes dissulfeto (–S–S–), ligações de H, iônicas, hidrofóbicas", "frente-4/bioquimica"], ["a-frente-4", "Aminoácidos e proteínas\nQuaternária\n(O que é, Estabilizada por)", "O que é: união de várias cadeias · Estabilizada por: as mesmas interações (ex.: hemoglobina, 4 cadeias)", "frente-4/bioquimica"], ["a-frente-4", "Aminoácidos e proteínas\nQuiralidade?", "o Cα é quiral em todos, exceto na glicina (R = H). Os da natureza são da série L .", "frente-4/bioquimica"], ["a-frente-4", "Aminoácidos e proteínas\nEssenciais?", "(o corpo humano não sintetiza; vêm da dieta): fenilalanina, valina, triptofano, treonina, lisina, leucina, isoleucina, metionina e histidina. Naturais (sintetizados): os demais.", "frente-4/bioquimica"], ["a-frente-4", "Aminoácidos e proteínas\nAnfóteros?", "reagem com ácidos e bases; em pH neutro estão como zwitterion (íon dipolar). O pH em que a carga líquida é zero é o ponto isoelétrico (pI) , onde a solubilidade é mínima.", "frente-4/bioquimica"], ["a-frente-4", "Aminoácidos e proteínas\nDesnaturação?", "perda da estrutura 2ª, 3ª (e 4ª) por calor, ácidos, bases, álcool, metais pesados ou agitação (clara de ovo cozida, leite coalhado). A sequência primária se mantém , mas a função biológica é perdida.", "frente-4/bioquimica"], ["a-frente-4", "Aminoácidos e proteínas\nEnzimas?", "proteínas catalisadoras, muito específicas (modelo chave-fechadura: o substrato se encaixa no sítio ativo); sensíveis à temperatura e ao pH. Terminam em \"-ase\" (amilase, lactase, lipase).", "frente-4/bioquimica"], ["a-frente-4", "Aminoácidos e proteínas\nFunções?", "estrutural (colágeno, queratina), transporte (hemoglobina), defesa (anticorpos), hormonal (insulina), contração (actina e miosina), catalítica (enzimas). Valor energético ≈ 4 kcal/g.", "frente-4/bioquimica"], ["a-frente-4", "Lipídios\nHidrogenação catalítica (Ni)\n(Esquema)", "Esquema: óleo + H₂ → gordura (margarina): satura as duplas", "frente-4/bioquimica"], ["a-frente-4", "Lipídios\nSaponificação\n(Esquema)", "Esquema: triglicerídeo + 3 NaOH → 3 sabão (sal de ác. graxo) + glicerol", "frente-4/bioquimica"], ["a-frente-4", "Lipídios\nTransesterificação\n(Esquema)", "Esquema: óleo + 3 metanol (ou etanol), catalisador básico (NaOH) → biodiesel (ésteres metílicos ou etílicos) + glicerol", "frente-4/bioquimica"], ["a-frente-4", "Lipídios\nRancificação (oxidação)\n(Esquema)", "Esquema: O₂ ataca as duplas do óleo e gera aldeídos e ácidos de cheiro forte", "frente-4/bioquimica"], ["a-frente-4", "Lipídios\nGlicerídeos (óleos e gorduras)?", "triésteres do glicerol (propano-1,2,3-triol) com 3 ácidos graxos: glicerol + 3 R–COOH → triglicerídeo + 3 H₂O.", "frente-4/bioquimica"], ["a-frente-4", "Lipídios\nCeras?", "éster de ácido graxo com álcool de cadeia longa (cera de abelha, carnaúba): impermeabilizam.", "frente-4/bioquimica"], ["a-frente-4", "Lipídios\nFosfolipídios?", "cabeça polar (fosfato) e 2 caudas apolares; formam a bicamada das membranas celulares.", "frente-4/bioquimica"], ["a-frente-4", "Lipídios\nEsteroides?", "estrutura de 4 anéis fundidos: colesterol, hormônios sexuais (testosterona, estradiol), cortisol, vitamina D.", "frente-4/bioquimica"], ["a-frente-4", "Carboidratos (glicídios)\nMonossacarídeos\n(Exemplos, Observações)", "Exemplos: Glicose (aldo-hexose), frutose (ceto-hexose), galactose; ribose e desoxirribose (pentoses) · Observações: não sofrem hidrólise. Glicose e frutose: C₆H₁₂O₆, isômeros de função. Glicose tem 4 C quirais (2⁴ = 16 isômeros ópticos); frutose, 3 (8).", "frente-4/bioquimica"], ["a-frente-4", "Carboidratos (glicídios)\nDissacarídeos\n(Exemplos, Observações)", "Exemplos: Sacarose = glicose + frutose; lactose = glicose + galactose; maltose = glicose + glicose · Observações: C₁₂H₂₂O₁₁. Ligação glicosídica, com perda de H₂O.", "frente-4/bioquimica"], ["a-frente-4", "Carboidratos (glicídios)\nPolissacarídeos\n(Exemplos, Observações)", "Exemplos: Amido , glicogênio , celulose , quitina · Observações: (C₆H₁₀O₅)ₙ, polímeros de glicose por condensação.", "frente-4/bioquimica"], ["a-frente-4", "Carboidratos (glicídios)\nAmido?", "reserva dos vegetais (batata, arroz, milho); digerido pela amilase; α-glicose. Glicogênio: reserva animal (fígado e músculos), mais ramificado. Celulose: função estrutural nas paredes celulares vegetais; β-glicose; o ser humano não a digere (falta a enzima), mas ela é fibra alimentar. Algodão e papel são celulose.", "frente-4/bioquimica"], ["a-frente-4", "Carboidratos (glicídios)\nHidrólise?", "sacarose + H₂O → glicose + frutose (açúcar invertido: a mistura gira o plano da luz polarizada no sentido oposto ao da sacarose). Lactose é quebrada pela lactase ; sua falta causa a intolerância à lactose.", "frente-4/bioquimica"], ["a-frente-4", "Carboidratos (glicídios)\nAçúcares redutores?", "(glicose, frutose, lactose, maltose) reduzem Cu²⁺ (reagentes de Benedict e Fehling) a Cu₂O (precipitado vermelho-tijolo). A sacarose não é redutora (as carbonilas estão ligadas entre si).", "frente-4/bioquimica"], ["a-frente-4", "Ácidos nucleicos\nPentose\n(DNA, RNA)", "DNA: desoxirribose · RNA: ribose", "frente-4/bioquimica"], ["a-frente-4", "Ácidos nucleicos\nBases\n(DNA, RNA)", "DNA: adenina (A), timina (T), citosina (C), guanina (G) · RNA: A, uracila (U) , C, G", "frente-4/bioquimica"], ["a-frente-4", "Ácidos nucleicos\nEstrutura\n(DNA, RNA)", "DNA: dupla hélice (Watson e Crick, 1953) · RNA: fita simples", "frente-4/bioquimica"], ["a-frente-4", "Ácidos nucleicos\nFunção\n(DNA, RNA)", "DNA: armazena a informação genética · RNA: síntese de proteínas (mRNA, tRNA, rRNA)", "frente-4/bioquimica"], ["a-organica", "Propriedades do carbono\nTetravalência?", "Z = 6 (1s² 2s² 2p²); faz 4 ligações covalentes.", "organica/fundamentos"], ["a-organica", "Propriedades do carbono\nEncadeamento?", "liga-se a outros carbonos formando cadeias longas, ramificadas ou em anel.", "organica/fundamentos"], ["a-organica", "Propriedades do carbono\nLigações múltiplas?", "simples, dupla ou tripla com outros carbonos e heteroátomos.", "organica/fundamentos"], ["a-organica", "Propriedades do carbono\nLigações σ e π?", "toda ligação simples é uma σ; a dupla tem 1σ + 1π; a tripla, 1σ + 2π.", "organica/fundamentos"], ["a-organica", "Classificação do carbono e das cadeias\nPrimário\n(Ligado a quantos outros carbonos)", "Ligado a quantos outros carbonos: 0 ou 1", "organica/fundamentos"], ["a-organica", "Classificação do carbono e das cadeias\nSecundário\n(Ligado a quantos outros carbonos)", "Ligado a quantos outros carbonos: 2", "organica/fundamentos"], ["a-organica", "Classificação do carbono e das cadeias\nTerciário\n(Ligado a quantos outros carbonos)", "Ligado a quantos outros carbonos: 3", "organica/fundamentos"], ["a-organica", "Classificação do carbono e das cadeias\nQuaternário\n(Ligado a quantos outros carbonos)", "Ligado a quantos outros carbonos: 4", "organica/fundamentos"], ["a-organica", "Classificação do carbono e das cadeias\nFechamento\n(Classes)", "Classes: Aberta (acíclica/alifática), fechada (cíclica) ou mista (parte aberta e parte fechada)", "organica/fundamentos"], ["a-organica", "Classificação do carbono e das cadeias\nDisposição\n(Classes)", "Classes: Normal (só carbonos primários e secundários, sem ramificação) ou ramificada (tem C terciário ou quaternário)", "organica/fundamentos"], ["a-organica", "Classificação do carbono e das cadeias\nLigações entre C\n(Classes)", "Classes: Saturada (só ligações simples) ou insaturada (dupla ou tripla entre carbonos)", "organica/fundamentos"], ["a-organica", "Classificação do carbono e das cadeias\nÁtomos na cadeia\n(Classes)", "Classes: Homogênea (só carbono) ou heterogênea (heteroátomo entre carbonos: O, N, S)", "organica/fundamentos"], ["a-organica", "Classificação do carbono e das cadeias\nAnel\n(Classes)", "Classes: Aromática (contém anel benzênico) ou alicíclica (cíclica não aromática)", "organica/fundamentos"], ["a-organica", "Funções orgânicas\nÁlcool?", "primário, secundário ou terciário, conforme o tipo do carbono que tem a hidroxila. Poliálcool: glicerol (3 OH).", "organica/funcoes-hidrocarbonetos"], ["a-organica", "Funções orgânicas\nAmina?", "primária (R–NH₂), secundária (R₂NH) ou terciária (R₃N), conforme o número de radicais ligados ao N.", "organica/funcoes-hidrocarbonetos"], ["a-organica", "Funções orgânicas\nFenol × álcool?", "no fenol a OH está em carbono do anel aromático; no álcool, em carbono saturado (sp³).", "organica/funcoes-hidrocarbonetos"], ["a-organica", "Isomeria\nCadeia?", "diferem no tipo de cadeia (C₄H₁₀).", "organica/isomeria-reacoes"], ["a-organica", "Isomeria\nPosição?", "diferem na posição do grupo funcional, insaturação ou ramificação (C₃H₈O).", "organica/isomeria-reacoes"], ["a-organica", "Isomeria\nFunção?", "funções diferentes (C₂H₆O).", "organica/isomeria-reacoes"], ["a-organica", "Isomeria\nMetameria?", "diferem na posição do heteroátomo (ex.: éteres, ésteres, aminas).", "organica/isomeria-reacoes"], ["a-organica", "Isomeria\nTautomeria?", "dois isômeros de função em equilíbrio dinâmico (aldeído/cetona ⇌ enol).", "organica/isomeria-reacoes"], ["a-organica", "Isomeria\nGeométrica (cis-trans ou E-Z)?", "exige dupla ligação (ou anel) e dois ligantes diferentes em cada carbono da dupla. Cis : ligantes iguais do mesmo lado; trans : lados opostos. Ex.: but-2-eno.", "organica/isomeria-reacoes"], ["a-organica", "Isomeria\nÓptica?", "exige carbono quiral (assimétrico: 4 ligantes diferentes). Os enantiômeros desviam o plano da luz polarizada em sentidos opostos: dextrógiro (+) e levógiro (−) . Mistura 1:1 dos dois é a mistura racêmica , opticamente inativa. Ex.: ácido lático, aminoácidos (exceto glicina).", "organica/isomeria-reacoes"], ["a-organica", "Reações orgânicas\nSubstituição em alcano\n(Exemplo, Observações)", "Exemplo: CH₄ + Cl₂ → CH₃Cl + HCl (luz ou calor) · Observações: Reatividade do H: C terciário > secundário > primário.", "organica/isomeria-reacoes"], ["a-organica", "Reações orgânicas\nSubstituição aromática\n(Exemplo, Observações)", "Exemplo: Benzeno + HNO₃ (H₂SO₄) → nitrobenzeno + H₂O. Também: halogenação (FeCl₃), sulfonação, alquilação de Friedel-Crafts. · Observações: Grupos orto-para dirigentes : –OH, –NH₂, –CH₃, –OR, halogênios. Grupos meta dirigentes : –NO₂, –COOH, –CHO, –SO₃H, –CN.", "organica/isomeria-reacoes"], ["a-organica", "Reações orgânicas\nAdição a alceno\n(Exemplo, Observações)", "Exemplo: + H₂ (Ni/Pt) → alcano; + X₂ → di-haleto vicinal; + HX → haleto; + H₂O (H⁺) → álcool · Observações: Regra de Markovnikov: o H do reagente vai para o carbono da dupla mais hidrogenado . A água de bromo descora na presença de alcenos e alcinos.", "organica/isomeria-reacoes"], ["a-organica", "Reações orgânicas\nAdição a alcino\n(Exemplo, Observações)", "Exemplo: Etino + H₂ → eteno → etano · Observações: Pode adicionar duas vezes (2 mols de reagente).", "organica/isomeria-reacoes"], ["a-organica", "Reações orgânicas\nEliminação\n(Exemplo, Observações)", "Exemplo: Etanol + H₂SO₄ conc. a 170 °C → eteno + H₂O (intramolecular). A 140 °C → éter dietílico (intermolecular). · Observações: Desidroalogenação de haleto com base forte forma alceno (regra de Saytzeff: forma-se o alceno mais substituído).", "organica/isomeria-reacoes"], ["a-organica", "Reações orgânicas\nOxidação de álcoois\n(Exemplo, Observações)", "Exemplo: Primário → aldeído → ácido carboxílico. Secundário → cetona. Terciário: não oxida em condições brandas. · Observações: Oxidantes: KMnO₄ ou K₂Cr₂O₇ em meio ácido.", "organica/isomeria-reacoes"], ["a-organica", "Reações orgânicas\nOxidação de alcenos\n(Exemplo, Observações)", "Exemplo: Ozonólise (O₃ e depois Zn/H₂O) → aldeídos e/ou cetonas · Observações: Oxidação enérgica quebra a dupla e pode gerar ácidos.", "organica/isomeria-reacoes"], ["a-organica", "Reações orgânicas\nRedução\n(Exemplo, Observações)", "Exemplo: Aldeído ou cetona + H₂ → álcool; nitrobenzeno → anilina; nitrila → amina · Observações: Inverso da oxidação.", "organica/isomeria-reacoes"], ["a-organica", "Reações orgânicas\nEsterificação\n(Exemplo, Observações)", "Exemplo: Ácido + álcool ⇌ éster + água (catálise ácida) · Observações: Reversível; a reação inversa é a hidrólise.", "organica/isomeria-reacoes"], ["a-organica", "Reações orgânicas\nSaponificação\n(Exemplo, Observações)", "Exemplo: Éster (óleo ou gordura) + NaOH → sal de ácido graxo (sabão) + glicerol · Observações: Hidrólise básica, irreversível.", "organica/isomeria-reacoes"], ["a-organica", "Reações orgânicas\nCombustão\n(Exemplo, Observações)", "Exemplo: Completa: CₓHᵧ + O₂ → CO₂ + H₂O. Incompleta: forma CO e/ou C (fuligem). · Observações: Libera energia; base dos combustíveis.", "organica/isomeria-reacoes"], ["a-organica", "Reações orgânicas\nPolimerização\n(Exemplo, Observações)", "Exemplo: Adição: n CH₂=CH₂ → (–CH₂–CH₂–)ₙ. Condensação: liberam moléculas pequenas (água). · Observações: Veja aplicações.", "organica/isomeria-reacoes"], ["a-organica", "Aplicações e compostos importantes\nPolietileno\n(Monômero, Tipo)", "Monômero: eteno · Tipo: adição", "organica/isomeria-reacoes"], ["a-organica", "Aplicações e compostos importantes\nPolipropileno\n(Monômero, Tipo)", "Monômero: propeno · Tipo: adição", "organica/isomeria-reacoes"], ["a-organica", "Aplicações e compostos importantes\nPVC\n(Monômero, Tipo)", "Monômero: cloreto de vinila (cloroeteno) · Tipo: adição", "organica/isomeria-reacoes"], ["a-organica", "Aplicações e compostos importantes\nPoliestireno\n(Monômero, Tipo)", "Monômero: estireno (vinilbenzeno) · Tipo: adição", "organica/isomeria-reacoes"], ["a-organica", "Aplicações e compostos importantes\nTeflon (PTFE)\n(Monômero, Tipo)", "Monômero: tetrafluoroeteno · Tipo: adição", "organica/isomeria-reacoes"], ["a-organica", "Aplicações e compostos importantes\nNáilon (poliamida)\n(Monômero, Tipo)", "Monômero: diácido + diamina · Tipo: condensação", "organica/isomeria-reacoes"], ["a-organica", "Aplicações e compostos importantes\nPET (poliéster)\n(Monômero, Tipo)", "Monômero: ácido tereftálico + etilenoglicol · Tipo: condensação", "organica/isomeria-reacoes"], ["a-organica", "Aplicações e compostos importantes\nCarboidratos?", "poli-hidroxialdeídos ou poli-hidroxicetonas, fórmula geral Cₙ(H₂O)ₘ. Ex.: glicose (C₆H₁₂O₆), sacarose, amido, celulose.", "organica/isomeria-reacoes"], ["a-organica", "Aplicações e compostos importantes\nLipídios?", "óleos e gorduras são triésteres de glicerol com ácidos graxos (ácidos carboxílicos de cadeia longa). Óleos têm insaturações e são líquidos; gorduras são saturadas e sólidas.", "organica/isomeria-reacoes"], ["a-organica", "Aplicações e compostos importantes\nProteínas?", "polímeros de α-aminoácidos unidos por ligação peptídica (–CO–NH–, uma amida).", "organica/isomeria-reacoes"], ["a-organica", "Aplicações e compostos importantes\nÁcidos nucleicos (DNA e RNA)?", "polímeros de nucleotídeos (açúcar, fosfato e base nitrogenada).", "organica/isomeria-reacoes"]];